# owner: platform
"""Plain text absence notices for parents."""

from typing import Iterable, List
from rosterkit.models import Mark, Student
from rosterkit.errors import ProjectError
from rosterkit.attendance import days_missed
from datetime import date

def format_day(day: date) -> str:
    return f"{day:%B} {day.day}, {day.year}"

def check_marks(
    student: Student, marks: List[Mark]
) -> None:
    """Refuse marks that belong to someone else."""
    for mark in marks:
        if mark.student_id != student.student_id:
            raise ProjectError(
                f"mark for {mark.student_id!r} does not "
                f"belong to {student.student_id!r}"
            )

def render_notice(
    student: Student, days: List[date]
) -> str:
    name = f"{student.first_name} {student.last_name}"
    noun = "day" if len(days) == 1 else "days"
    head = f"{name} missed {len(days)} {noun} of school:"
    lines = [f"- {format_day(day)}" for day in days]
    return "\n".join([head] + lines)

def build_notice(
    student: Student, marks: Iterable[Mark]
) -> str:
    """Notice with the student, count and dates."""
    marks = list(marks)
    check_marks(student, marks)
    days = days_missed(marks)
    if not days:
        raise ProjectError("no absences to write about")
    return render_notice(student, days)
